mapper.update:
UPDATE generation_task_step s JOIN generation_task t ON t.id=s.task_id
SET s.status='SUCCEEDED',s.finished_at=#{now},s.message=#{message}
WHERE s.task_id=#{id} AND s.stage=#{stage} AND s.status='RUNNING' AND t.status='PROCESSING' AND t.stage=#{stage}

UPDATE generation_task_step s JOIN generation_task t ON t.id=s.task_id
SET s.status='FAILED',s.finished_at=#{now},s.message=#{message}
WHERE s.task_id=#{id} AND s.stage=#{stage} AND s.status='RUNNING' AND t.status='FAILED' AND t.failed_stage=#{stage}
